import { Link } from "react-router-dom";
import { useState } from "react";
import LocationSelector from "../components/LocationSelector";

// ======================================================
// API URL
// ======================================================
// LOCAL BACKEND:
// http://localhost:5000/api
//
// When deploying, set VITE_API_URL in .env
// ======================================================

const API_URL =
  import.meta.env.VITE_API_URL ||
  "http://localhost:5000/api";

// ======================================================
// DISEASE / PROBLEM LIST
// ======================================================

const diseases = [
  "Fever",
  "Cold",
  "Cough",
  "Headache",
  "Stomach Pain",
  "Skin Problem",
  "Diabetes",
  "Blood Pressure",
  "Chest Pain",
  "Injury",
  "General Checkup",
  "Other",
];

// ======================================================
// COMPONENT
// ======================================================

function Hospitals() {
  const [location, setLocation] = useState(null);

  const [hospitals, setHospitals] = useState([]);

  const [selectedHospital, setSelectedHospital] =
    useState(null);

  const [problem, setProblem] =
    useState("Fever");

  const [typedProblem, setTypedProblem] =
    useState("");

  const [doctors, setDoctors] =
    useState([]);

  const [selectedDoctor, setSelectedDoctor] =
    useState(null);

  const [patientName, setPatientName] =
    useState("");

  const [token, setToken] =
    useState(null);

  const [loading, setLoading] =
    useState(false);

  const [error, setError] =
    useState("");

  // ======================================================
  // SELECTED PROBLEM
  // ======================================================

  const selectedProblem =
    problem === "Other"
      ? typedProblem.trim() || "Other"
      : problem;

  // ======================================================
  // LOAD HOSPITALS
  // ======================================================

  const loadHospitals = async (selectedLocation) => {
    setLocation(selectedLocation);

    setSelectedHospital(null);
    setSelectedDoctor(null);
    setDoctors([]);
    setToken(null);
    setError("");

    try {
      setLoading(true);

      const params = new URLSearchParams();

      if (
        selectedLocation &&
        selectedLocation.method === "manual"
      ) {
        params.set(
          "state",
          selectedLocation.state || ""
        );

        params.set(
          "district",
          selectedLocation.district || ""
        );

        params.set(
          "village",
          selectedLocation.village || ""
        );
      }

      const url =
        `${API_URL}/hospitals?${params.toString()}`;

      console.log(
        "Loading hospitals from:",
        url
      );

      const response =
        await fetch(url);

      const data =
        await response.json();

      console.log(
        "Hospital response:",
        data
      );

      if (!response.ok) {
        throw new Error(
          data.message ||
          "Unable to load hospitals"
        );
      }

      setHospitals(
        data.hospitals || []
      );

      if (
        !data.hospitals ||
        data.hospitals.length === 0
      ) {
        setError(
          "No hospitals found for the selected location."
        );
      }

    } catch (err) {
      console.error(
        "Load hospitals error:",
        err
      );

      setError(
        err.message ||
        "Unable to connect to backend."
      );

    } finally {
      setLoading(false);
    }
  };

  // ======================================================
  // LOAD DOCTORS
  // ======================================================

  const loadDoctors = async (hospital) => {

    if (!hospital || !hospital._id) {
      setError(
        "Hospital information is missing."
      );
      return;
    }

    setSelectedHospital(hospital);
    setSelectedDoctor(null);
    setDoctors([]);
    setToken(null);
    setError("");

    try {
      setLoading(true);

      // ----------------------------------------------
      // BUILD DOCTOR API URL
      // ----------------------------------------------

      const url =
        `${API_URL}/hospitals/${hospital._id}/doctors?problem=${encodeURIComponent(
          selectedProblem
        )}`;

      console.log(
        "Loading doctors from:",
        url
      );

      // ----------------------------------------------
      // API REQUEST
      // ----------------------------------------------

      const response =
        await fetch(url);

      const data =
        await response.json();

      console.log(
        "Doctor response:",
        data
      );

      // ----------------------------------------------
      // API ERROR
      // ----------------------------------------------

      if (!response.ok) {
        throw new Error(
          data.message ||
          "Unable to load doctors"
        );
      }

      // ----------------------------------------------
      // SET DOCTORS
      // ----------------------------------------------

      const doctorList =
        Array.isArray(data.doctors)
          ? data.doctors
          : [];

      setDoctors(doctorList);

      // ----------------------------------------------
      // NO DOCTOR MESSAGE
      // ----------------------------------------------

      if (doctorList.length === 0) {
        setError(
          `No doctors found for "${selectedProblem}" at ${hospital.name}.`
        );
      }

    } catch (err) {

      console.error(
        "Load doctors error:",
        err
      );

      setDoctors([]);

      setError(
        err.message ||
        "Unable to load doctors. Check whether backend is running."
      );

    } finally {
      setLoading(false);
    }
  };

  // ======================================================
  // BOOK APPOINTMENT
  // ======================================================

  const bookAppointment = async () => {

    if (
      !patientName.trim() ||
      !selectedHospital ||
      !selectedDoctor
    ) {
      setError(
        "Enter patient name and select a doctor."
      );
      return;
    }

    try {
      setLoading(true);
      setError("");

      const response =
        await fetch(
          `${API_URL}/hospitals/tokens`,
          {
            method: "POST",

            headers: {
              "Content-Type":
                "application/json",
            },

            body: JSON.stringify({
              patientName:
                patientName.trim(),

              hospitalId:
                selectedHospital._id,

              doctorId:
                selectedDoctor._id,

              problem:
                selectedProblem,

              source: "online",
            }),
          }
        );

      const data =
        await response.json();

      if (!response.ok) {
        throw new Error(
          data.message ||
          "Unable to book appointment"
        );
      }

      localStorage.setItem(
        "queueless_hospital_token",
        JSON.stringify(data.token)
      );

      setToken(data.token);

    } catch (err) {

      console.error(
        "Book appointment error:",
        err
      );

      setError(
        err.message ||
        "Unable to book appointment"
      );

    } finally {
      setLoading(false);
    }
  };

  // ======================================================
  // UI
  // ======================================================

  return (
    <main className="min-h-screen bg-slate-50 px-6 py-16">

      <div className="mx-auto max-w-5xl">

        {/* BACK */}

        <Link
          to="/"
          className="font-semibold text-blue-700"
        >
          Back to Home
        </Link>

        {/* PAGE HEADER */}

        <div className="mt-6">

          <p className="text-sm font-semibold uppercase tracking-wider text-blue-700">
            Hospitals
          </p>

          <h1 className="mt-2 text-3xl font-bold text-slate-900">
            Find nearby hospitals
          </h1>

        </div>

        {/* LOCATION */}

        <div className="mt-8">
          <LocationSelector
            onLocationSelected={
              loadHospitals
            }
          />
        </div>

        {/* ERROR */}

        {error && (
          <div className="mt-6 rounded-xl bg-red-50 border border-red-200 p-4 text-sm font-medium text-red-700">
            {error}
          </div>
        )}

        {/* ==================================================
            HOSPITALS
        ================================================== */}

        {location && (
          <section className="mt-8">

            <h2 className="text-xl font-bold text-slate-900">
              Hospitals
            </h2>

            {/* LOADING */}

            {loading && (
              <p className="mt-4 text-slate-500">
                Loading...
              </p>
            )}

            {/* HOSPITAL CARDS */}

            <div className="mt-4 grid gap-4 md:grid-cols-2">

              {hospitals.map(
                (hospital) => (
                  <button
                    key={hospital._id}
                    type="button"
                    onClick={() =>
                      loadDoctors(
                        hospital
                      )
                    }
                    className="rounded-2xl border border-slate-200 bg-white p-5 text-left shadow-sm transition hover:border-blue-300 hover:shadow-md"
                  >

                    <h3 className="font-bold text-slate-900">
                      {hospital.name}
                    </h3>

                    <p className="mt-1 text-sm text-slate-500">
                      {hospital.village},{" "}
                      {hospital.district}
                    </p>

                    <p className="mt-3 text-sm font-semibold text-green-700">
                      {
                        hospital.availableDoctors ??
                        0
                      }{" "}
                      doctors available
                    </p>

                    <p className="text-sm text-slate-500">
                      {
                        hospital.waitingCount ??
                        0
                      }{" "}
                      people waiting
                    </p>

                  </button>
                )
              )}

            </div>

          </section>
        )}

        {/* ==================================================
            PROBLEM SELECTION
        ================================================== */}

        {selectedHospital && (
          <section className="mt-8 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">

            <h2 className="text-xl font-bold text-slate-900">
              Select disease or problem
            </h2>

            <div className="mt-4 flex flex-wrap gap-2">

              {diseases.map(
                (item) => (

                  <button
                    key={item}
                    type="button"
                    onClick={() => {
                      setProblem(item);
                      setDoctors([]);
                      setSelectedDoctor(null);
                      setError("");
                    }}
                    className={`rounded-full px-4 py-2 text-sm font-semibold transition ${
                      problem === item
                        ? "bg-blue-700 text-white"
                        : "bg-slate-100 text-slate-700 hover:bg-slate-200"
                    }`}
                  >
                    {item}
                  </button>

                )
              )}

            </div>

            {/* OTHER */}

            {problem === "Other" && (
              <input
                value={typedProblem}
                onChange={(event) =>
                  setTypedProblem(
                    event.target.value
                  )
                }
                placeholder="Type your problem"
                className="mt-4 w-full rounded-xl border border-slate-300 px-4 py-3 outline-none focus:border-blue-600"
              />
            )}

            {/* FIND DOCTORS */}

            <button
              type="button"
              onClick={() =>
                loadDoctors(
                  selectedHospital
                )
              }
              disabled={loading}
              className="mt-5 rounded-xl bg-slate-900 px-5 py-3 font-semibold text-white transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {loading
                ? "Finding Doctors..."
                : "Find Doctors"}
            </button>

          </section>
        )}

        {/* ==================================================
            NO DOCTORS
        ================================================== */}

        {selectedHospital &&
          !loading &&
          doctors.length === 0 &&
          !error && (
            <section className="mt-8 rounded-2xl border border-yellow-200 bg-yellow-50 p-6">

              <h2 className="font-bold text-yellow-900">
                No doctors found
              </h2>

              <p className="mt-2 text-sm text-yellow-800">
                No doctor is currently registered
                for {selectedProblem} at{" "}
                {selectedHospital.name}.
              </p>

            </section>
          )}

        {/* ==================================================
            DOCTORS
        ================================================== */}

        {doctors.length > 0 && (
          <section className="mt-8">

            <h2 className="text-xl font-bold text-slate-900">
              Relevant Doctors
            </h2>

            <p className="mt-1 text-sm text-slate-500">
              Doctors available for:{" "}
              <strong>
                {selectedProblem}
              </strong>
            </p>

            <div className="mt-4 grid gap-4 md:grid-cols-2">

              {doctors.map(
                (doctor) => (

                  <button
                    key={doctor._id}
                    type="button"
                    onClick={() =>
                      setSelectedDoctor(
                        doctor
                      )
                    }
                    className={`rounded-2xl border bg-white p-5 text-left shadow-sm transition ${
                      selectedDoctor?._id ===
                      doctor._id
                        ? "border-blue-600 ring-2 ring-blue-100"
                        : "border-slate-200 hover:border-blue-300"
                    }`}
                  >

                    <h3 className="font-bold text-slate-900">
                      {doctor.name}
                    </h3>

                    <p className="mt-1 text-sm text-slate-500">
                      {doctor.specialization}
                      {" • "}
                      Room {doctor.room}
                    </p>

                    {/* AVAILABLE */}

                    {doctor.available ? (

                      <div className="mt-4 text-sm">

                        <p className="font-bold text-green-700">
                          Doctor Available
                        </p>

                        <p className="mt-1">
                          People Waiting:{" "}
                          {doctor.peopleWaiting ??
                            0}
                        </p>

                        <p>
                          Estimated Waiting Time:{" "}
                          {doctor.estimatedWaitingTime ??
                            0}{" "}
                          minutes
                        </p>

                      </div>

                    ) : (

                      <div className="mt-4 text-sm">

                        <p className="font-bold text-red-700">
                          Doctor Not Available
                        </p>

                        <p className="mt-1">
                          Expected Arrival:{" "}
                          {doctor.expectedArrival ||
                            "Not updated"}
                        </p>

                      </div>

                    )}

                  </button>

                )
              )}

            </div>

          </section>
        )}

        {/* ==================================================
            BOOK APPOINTMENT
        ================================================== */}

        {selectedDoctor && (
          <section className="mt-8 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">

            <h2 className="text-xl font-bold text-slate-900">
              Book Appointment
            </h2>

            <p className="mt-2 text-sm text-slate-500">
              Selected Doctor:{" "}
              <strong>
                {selectedDoctor.name}
              </strong>
            </p>

            <input
              value={patientName}
              onChange={(event) =>
                setPatientName(
                  event.target.value
                )
              }
              placeholder="Patient name"
              className="mt-4 w-full rounded-xl border border-slate-300 px-4 py-3 outline-none focus:border-blue-600"
            />

            <button
              type="button"
              onClick={bookAppointment}
              disabled={
                !selectedDoctor.available ||
                loading
              }
              className="mt-4 rounded-xl bg-blue-700 px-5 py-3 font-semibold text-white hover:bg-blue-800 disabled:opacity-50"
            >
              {loading
                ? "Booking..."
                : "Book Appointment"}
            </button>

          </section>
        )}

        {/* ==================================================
            TOKEN
        ================================================== */}

        {token && (
          <section className="mt-8 rounded-3xl border border-green-200 bg-green-50 p-6">

            <h2 className="text-xl font-bold text-green-900">
              Appointment Booked
            </h2>

            <div className="mt-4 grid gap-3 text-sm md:grid-cols-2">

              <Info
                label="Hospital"
                value={
                  token.hospital?.name
                }
              />

              <Info
                label="Doctor"
                value={
                  token.doctor?.name
                }
              />

              <Info
                label="Token"
                value={
                  token.tokenNumber
                }
              />

              <Info
                label="Expected Time"
                value={
                  token.expectedTime
                }
              />

              <Info
                label="Room"
                value={
                  token.doctor?.room
                }
              />

              <Info
                label="People Ahead"
                value="Calculated live"
              />

            </div>

            <Link
              to={`/hospital-queue/${token._id}`}
              className="mt-5 inline-block rounded-xl bg-blue-700 px-5 py-3 font-semibold text-white"
            >
              Track Live Queue
            </Link>

          </section>
        )}

      </div>

    </main>
  );
}

// ======================================================
// INFO COMPONENT
// ======================================================

function Info({ label, value }) {
  return (
    <div className="rounded-xl bg-white p-4">

      <p className="text-xs font-semibold uppercase text-slate-400">
        {label}
      </p>

      <p className="mt-1 font-bold text-slate-900">
        {value || "Not available"}
      </p>

    </div>
  );
}

export default Hospitals;
